  identity: EvidenceCommandIdentity,
  overrides: unknown,
  defaultMs: number = DEFAULT_VALIDATE_COMMAND_TIMEOUT_MS,
): number {
  const boundedDefault = Math.max(1, Math.min(MAX_NODE_TIMER_DELAY_MS, Math.floor(defaultMs)));
